using System.Windows;
using Tune.Client.Controllers;
using Tune.Generic.DialogGenerics;
using Tune.Helpers;
using Tune.Models.Dialog;
using Tune.Models.Music;
using Tune.Models.Playlist;
using Tune.Services.FileDialog;
using Tune.Values.Config;
using Tune.Values.Static;

// Initially generated by AI, but edited.
namespace Tune.Components.UI
{
    public partial class AddMusic : DialogBaseObjectMusic
    {
        private Music? _currentMusic;
        // ==== Internal Properties ====
        private Music? SelectedMusic { get; set; }

        // ==== Implement Interfaces ====
        public override Music? Result
        {
            get => SelectedMusic;
            set => SelectedMusic = value;
        }

        private object? _argument;

        public override object? Argument
        {
            get => _argument;
            set
            {
                _argument = value;
            }
        }

        // ==== Constructor ====
        public AddMusic(Music? currentMusic)
        {
            InitializeComponent();
            this.DataContext = this;
            this.Height = 260;
            this.Width = 800;

            _currentMusic = currentMusic;

            ConfirmButton.Click += OnConfirmClick;
            CancelButton.Click += OnCancelClick;
        }

        // ==== UI Logic ====
        private void OnConfirmClick(object sender, RoutedEventArgs e)
        {

            RaiseConfirm();
        }

        private void OnCancelClick(object sender, RoutedEventArgs e)
        {
            SelectedMusic = null;
            RaiseCancel();
        }

        private void UpdateSelectedMusicDisplay()
        {
            if (SelectedMusic != null)
            {
                SelectMusicButton.Text = SelectedMusic.Metadata.Title;
            }
            else
            {
                SelectMusicButton.Text = Strings.NO_CONTENT;
            }
        }

        private void OnSelectNowPlayingClick(object sender, RoutedEventArgs e)
        {
            SelectedMusic = _currentMusic;
            UpdateSelectedMusicDisplay();
        }

        private void OnSelectMusicButtonClick(object sender, RoutedEventArgs e)
        {
            var _fileDialogService = new FileDialogService();
            var filePath = _fileDialogService.OpenMusicFile();
            if (string.IsNullOrEmpty(filePath))
            {
                return;
            }
            SelectedMusic = new Music(filePath);
            if (SelectedMusic.notExists)
            {
                // TODO SHOW_TOAST
                MessageBox.Show("Music not exists or unknown problem", Strings.APPLICATION_NAME, MessageBoxButton.OK, MessageBoxImage.Information);
                SelectedMusic = null;
            }
            UpdateSelectedMusicDisplay();


        }

    }
}